import sys,json,hashlib,pathlib,shutil,subprocess,os
mem={p.split()[0].rstrip(':'):int(p.split()[1])*1024 for p in pathlib.Path('/proc/meminfo').read_text().splitlines() if p.startswith('MemAvailable:')}
guard={'mem_available_bytes':mem['MemAvailable'],'private_free_bytes':shutil.disk_usage('/dev').free,'filesystem_writes':0,'application_imports':0}
assert guard['mem_available_bytes']>=2*1024**3 and guard['private_free_bytes']>=128*1024**2,guard
obj=json.loads(sys.argv[1])
compile(obj['python'],'compare.py','exec')
node=shutil.which('node')
assert node,'Existing Node required for syntax only'
r=subprocess.run([node,'--check','--input-type=module'],input=obj['node'],text=True,capture_output=True,timeout=10)
def pin(s):
 b=s.encode('utf-8');return {'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'git_blob':hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()}
print(json.dumps({'guard':guard,'python_compile':'pass','node_syntax_exit':r.returncode,'node_syntax_stdout':r.stdout,'node_syntax_stderr':r.stderr,'node':node,'sources':{'receive.mjs':pin(obj['node']),'compare.py':pin(obj['python'])}},ensure_ascii=False))
raise SystemExit(r.returncode)

