import sys,json,hashlib,pathlib,shutil
mem={p.split()[0].rstrip(':'):int(p.split()[1])*1024 for p in pathlib.Path('/proc/meminfo').read_text().splitlines() if p.startswith('MemAvailable:')}
guard={'mem_available_bytes':mem['MemAvailable'],'private_free_bytes':shutil.disk_usage('/dev').free,'filesystem_writes':0,'application_imports':0}
assert guard['mem_available_bytes']>=2*1024**3 and guard['private_free_bytes']>=128*1024**2,guard
obj=json.loads(sys.argv[1]);results={}
for name,source in obj.items():
 compile(source,name,'exec')
 b=source.encode('utf-8')
 results[name]={'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'git_blob':hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()}
print(json.dumps({'compile':'pass','guard':guard,'sources':results}))
